    restoreDraft(); renderDays(); updateAllWeather(); renderSaved(); locale(section); var tripLangButton=document.getElementById("langToggle");if(tripLangButton)tripLangButton.addEventListener("click",function(){setTimeout(function(){locale(section);renderDays();renderSaved()},30)});
